def get_end_of_life_care_priority(patient):
    """
    Compute the end-of-life care priority of the patient.
    patient: A patient object with attributes: duration_of_condition, age, symptoms, race, severity, comorbidities, resource_availability
    """
    score = 0

    # Increase priority based on the length of the condition,
    # likely the patient is nearing the end of life if the condition lasts long
    if patient.duration_of_condition > 12:  # more than 3 months
        score += 3
    elif patient.duration_of_condition > 6:  # 1 to 3 months
        score += 2
    else:
        score += 1

    # Increase priority based on disease severity
    # The more severe the disease, the more important the end-of-life care is
    if patient.severity >= 8:
        score += 3
    elif patient.severity >= 7:
        score += 2
    else:
        score += 1

    # Older patients need more care especially in their last days or weeks
    if patient.age > 65:
        score += 3
    elif patient.age > 50:
        score += 2
    else:
        score += 1

    # The more severe the symptoms, the more important the care is
    if 'ongoing fatigue' in patient.symptoms or 'chronic pain' in patient.symptoms:
        score += 3
    elif 'reduced mobility' in patient.symptoms:
        score += 2
    else:
        score += 1

    # Consider comorbidities, the more the comorbidity, the more critical the disease,
    # and hence the end-of-life care is more critical
    if patient.comorbidities >= 4:
        score += 3
    elif patient.comorbidities >= 3:
        score += 2
    else:
        score += 1

    # Consider patient's race, the race that needs more care should obtain larger scores
    if patient.race == 'Black' or patient.race == 'Hispanic':
        score += 3
    elif patient.race == 'Asian':
        score += 2

    # If the patient doesn't have enough resources, reduce the priority of the care
    # Make sure that only necessary care is provided if resources are limited
    if patient.resource_availability == 'low':
        score -= 2

    return max(0, score)

