def get_advance_care_planning_priority(patient):
    """
    Compute the advance care planning priority of the patient.
    patient: A patient object with attributes: comorbidities, age, severity, resource_availability, race, duration_of_condition, symptoms
    """
    score = 0

    # Higher number of comorbidities increases priority
    score += patient.comorbidities * 2

    # Age can also influence the urgency of advance care planning: the older the patient, the higher the priority
    if patient.age >= 75:
        score += 5
    elif patient.age >= 65:
        score += 4
    elif patient.age >= 55:
        score += 3
    elif patient.age >= 45:
        score += 2
    else:
        score += 1

    # The severity of the condition is a critical factor—the more severe the condition, the higher the priority
    score += patient.severity * 2

    # Resource availability may also affect priority
    if patient.resource_availability == 'limited':
        score += 2
    elif patient.resource_availability == 'moderate':
        score += 1

    # The patient's race could have an impact; in some cultures or communities, race should be assigned higher scores
    if patient.race == 'African American' or patient.race == 'Hispanic':
        score += 3
    elif patient.race == 'Asian' or patient.race == 'Caucasian':
        score += 2
    else:
        score += 1

    # If the patient's condition has been longer, this necessitates a higher priority for advance care planning
    score += patient.duration_of_condition * 2

    # Symptom severity might affect priority, especially as it can be a sign of progression or worsening of the condition
    symptom_severity = 0
    if 'chronic pain' in patient.symptoms:
        symptom_severity += 3
    elif 'reduced mobility' in patient.symptoms or 'ongoing fatigue' in patient.symptoms:
        symptom_severity += 2
    else:
        symptom_severity += 1
    score += symptom_severity

    return score

